using DroidLab.Devices;
using System.Windows;
using System.Windows.Controls;
namespace DroidLab.Desktop;
public partial class MainWindow : Window {
 private static readonly string[] Modules = ["Command Center","Device Intelligence","Diagnostics Lab","Troubleshooting Lab","ADB Workbench","Fastboot Lab","Firmware & Flashing","Recovery Center","Backup & Restoration","Technician Center","SIM & Network Lab","Security & CVE Lab","Application Manager","File & Storage Lab","Connectivity Lab","Reporting Center"];
 public MainWindow(){InitializeComponent(); Navigation.ItemsSource=Modules; DiagnosticPicker.ItemsSource=Enum.GetValues<DiagnosticKind>();DiagnosticPicker.SelectedIndex=0;BackupPicker.ItemsSource=Enum.GetValues<BackupFolder>();BackupPicker.SelectedIndex=0;RebootPicker.ItemsSource=Enum.GetValues<RebootTarget>();RebootPicker.SelectedIndex=0;Navigation.SelectedIndex=0;}
 private void Navigate(object sender, SelectionChangedEventArgs e){if(Navigation.SelectedItem is not string name)return; Heading.Text=name;CvePanel.Visibility=name=="Security & CVE Lab"?Visibility.Visible:Visibility.Collapsed; bool ready=name=="Security & CVE Lab"||name=="Command Center"||name=="ADB Workbench"||name=="Fastboot Lab"||name=="Device Intelligence"||name=="Diagnostics Lab"||name=="Application Manager"||name=="File & Storage Lab"; bool backup=name=="Backup & Restoration";bool recovery=name=="Recovery Center";VerifyPanel.Visibility=backup?Visibility.Visible:Visibility.Collapsed;RebootPanel.Visibility=recovery?Visibility.Visible:Visibility.Collapsed;BackupPanel.Visibility=backup?Visibility.Visible:Visibility.Collapsed;bool firmware=name=="Firmware & Flashing"; FirmwarePanel.Visibility=firmware?Visibility.Visible:Visibility.Collapsed; Description.Text=name=="Security & CVE Lab"?"Read device identity to assess reported patch age and verified boot. Public CVE search is available; device-specific correlation is not yet implemented.":backup?"Copy accessible shared storage to a new local folder. Protected app data is not included.":recovery?"Detect recovery modes and request an explicitly confirmed reboot.":firmware?"Inspect local firmware without modifying any device. A checksum match does not establish compatibility or authenticity.":ready?"Read-only ADB and Fastboot discovery. Connect an authorized device with USB debugging enabled.":"Planned module — not implemented in this foundation build."; Scan.Visibility=ready||backup||recovery?Visibility.Visible:Visibility.Collapsed;DiagnosticPanel.Visibility=ready||backup||recovery?Visibility.Visible:Visibility.Collapsed;Output.Visibility=ready||firmware||backup||recovery?Visibility.Visible:Visibility.Collapsed;Output.Clear();}
 private async void Detect(object sender,RoutedEventArgs e){Scan.IsEnabled=false;Output.Text="Detecting devices...";try{var results=await Task.WhenAll(Discovery.ScanAsync("ADB"),Discovery.ScanAsync("Fastboot"));DevicePicker.ItemsSource=results.SelectMany(r=>r.Devices).Where(d=>d.Transport=="ADB"&&d.State=="device").ToList();DevicePicker.SelectedIndex=0;Output.Text=string.Join("\n\n",results.Select(r=>r.Transport+": "+(r.Error??(r.Devices.Count==0?"No devices":string.Join("\n",r.Devices.Select(d=>$"{d.Serial} | {d.State} | {d.Details} | {RecoveryReadiness.Describe(d)}"))))));}catch(Exception ex){Output.Text=ex.Message;}finally{Scan.IsEnabled=true;}}
 private async void ReadDiagnostic(object sender,RoutedEventArgs e){if(DevicePicker.SelectedItem is not Device device||DiagnosticPicker.SelectedItem is not DiagnosticKind kind){Output.Text="Select an authorized device after discovery.";return;}ReadButton.IsEnabled=false;try{var security=Navigation.SelectedItem as string=="Security & CVE Lab";var raw=await Diagnostics.ReadAsync(device,security?DiagnosticKind.Identity:kind);if(security||kind==DiagnosticKind.Identity){var identity=IdentityParser.Parse(raw);var oem=OemCompatibility.Identify(identity.Manufacturer);Output.Text=$"Manufacturer: {identity.Manufacturer}\nModel: {identity.Model}\nProduct: {identity.Product}\nAndroid: {identity.AndroidVersion}\nFingerprint: {identity.BuildFingerprint}\nSuggested transport: {oem.SuggestedTransport}\n\n"+string.Join("\n",SecurityAssessment.Assess(identity,DateOnly.FromDateTime(DateTime.UtcNow)).Select(x=>$"{x.Code} | {x.Status} | {x.Detail}"));}else Output.Text=raw;}catch(Exception ex){Output.Text=ex.Message;}finally{ReadButton.IsEnabled=true;}}
 private void BrowseFirmware(object sender,RoutedEventArgs e){var dialog=new Microsoft.Win32.OpenFileDialog{Filter="Firmware files|*.zip;*.img;*.tar;*.md5;*.bin|All files|*.*",CheckFileExists=true};if(dialog.ShowDialog()==true)FirmwarePath.Text=dialog.FileName;}
 private async void InspectFirmware(object sender,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(FirmwarePath.Text)){Output.Text="Select a firmware file first.";return;}InspectButton.IsEnabled=false;try{Output.Text="Inspecting file...";var expected=ExpectedHash.Text.Trim();var result=await FirmwareInspector.InspectAsync(FirmwarePath.Text,expected.Length==0?null:expected);Output.Text=$"File: {result.Name}\nBytes: {result.Bytes}\nSHA-256: {result.Sha256}\nChecksum: {result.MatchesExpected switch {true=>"Match",false=>"MISMATCH",null=>"Not compared"}}\n\nZIP inventory (up to 1000 entries):\n"+string.Join("\n",result.Entries);}catch(Exception ex){Output.Text="Inspection failed: "+ex.Message;}finally{InspectButton.IsEnabled=true;}}
 private async void RunBackup(object sender,RoutedEventArgs e){if(DevicePicker.SelectedItem is not Device device||BackupPicker.SelectedItem is not BackupFolder folder){Output.Text="Detect and select an authorized device first.";return;}var dialog=new Microsoft.Win32.OpenFolderDialog{Title="Select backup destination"};if(dialog.ShowDialog()!=true)return;if(MessageBox.Show($"Copy {folder} from {device.Serial} to a new folder in the selected destination?","Confirm backup",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;BackupButton.IsEnabled=false;try{Output.Text="Copying files...";var result=await SharedStorageBackup.RunAsync(device,folder,dialog.FolderName);Output.Text=$"Backup complete: {result.FileCount} files\n{result.Directory}\nManifest: {result.ManifestPath}";}catch(Exception ex){Output.Text="Backup failed or incomplete: "+ex.Message;}finally{BackupButton.IsEnabled=true;}}
 private async void RestoreBackup(object sender,RoutedEventArgs e){if(DevicePicker.SelectedItem is not Device device){Output.Text="Select an authorized device first.";return;}var dialog=new Microsoft.Win32.OpenFolderDialog{Title="Select backup root"};if(dialog.ShowDialog()!=true)return;if(MessageBox.Show($"Restore verified backup to a new Download staging folder on {device.Serial}? Original folders will not be overwritten.","Confirm restoration",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;RestoreButton.IsEnabled=false;try{Output.Text="Verifying and transferring backup...";var result=await SharedStorageRestore.RunAsync(device,dialog.FolderName);Output.Text=$"ADB transfer completed: {result.FileCount} manifest files. Staging: {result.Destination}. Device-side checksum verification not performed.";}catch(Exception ex){Output.Text="Restoration failed: "+ex.Message;}finally{RestoreButton.IsEnabled=true;}}
 private async void VerifyBackup(object sender,RoutedEventArgs e){var dialog=new Microsoft.Win32.OpenFolderDialog{Title="Select backup root containing manifest.json"};if(dialog.ShowDialog()!=true)return;VerifyButton.IsEnabled=false;try{Output.Text="Verifying backup...";var result=await BackupVerification.VerifyAsync(dialog.FolderName);Output.Text=result.Valid?"Backup matches manifest.":"Verification failed:\n"+string.Join("\n",result.Issues);}catch(Exception ex){Output.Text="Verification failed: "+ex.Message;}finally{VerifyButton.IsEnabled=true;}}
 private async void RequestReboot(object sender,RoutedEventArgs e){if(DevicePicker.SelectedItem is not Device device||RebootPicker.SelectedItem is not RebootTarget target){Output.Text="Select an authorized online device.";return;}if(MessageBox.Show($"Reboot {device.Serial} into {target}? Save your work first.","Confirm reboot",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;RebootButton.IsEnabled=false;try{await DeviceReboot.RequestAsync(device,target);Output.Text="Reboot requested. Rescan to verify the resulting mode.";}catch(Exception ex){Output.Text=ex.Message;}finally{RebootButton.IsEnabled=true;}}
 private readonly AdvisoryCache advisoryCache=new(System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DroidLab","Advisories"));
 private AdvisorySnapshot? currentAdvisory;
 private void ShowAdvisory(AdvisorySnapshot snapshot,bool cached){currentAdvisory=snapshot;Output.Text=$"{(cached?"CACHED — may be stale":"LIVE")} | {snapshot.Keyword} | Retrieved {snapshot.RetrievedAt:u}\nPublic advisory matches, not confirmed device vulnerabilities. Maximum 50 results.\n\n"+(snapshot.Advisories.Count==0?"No matches returned.":string.Join("\n\n",snapshot.Advisories.Select(x=>$"{x.Id} | CVSS: {x.Score?.ToString()??"Unknown"} | CISA KEV: {(x.KnownExploited?"Listed":"Not listed")}\n{x.Description}")));}
 private async void LoadCachedCve(object sender,RoutedEventArgs e){currentAdvisory=null;try{var snapshot=await advisoryCache.ReadAsync(CveKeyword.Text);if(snapshot==null)Output.Text="No cached results for this keyword.";else ShowAdvisory(snapshot,true);}catch(Exception ex){Output.Text="Cache read failed: "+ex.Message;}}
 private async void ExportCve(object sender,RoutedEventArgs e){var snapshot=currentAdvisory;if(snapshot==null){Output.Text="Search or load cached results first.";return;}var dialog=new Microsoft.Win32.SaveFileDialog{Filter="JSON report|*.json",FileName="DroidLab-Advisories.json"};if(dialog.ShowDialog()!=true)return;try{await System.IO.File.WriteAllTextAsync(dialog.FileName,AdvisoryCache.Report(snapshot));Output.Text="Report exported: "+dialog.FileName;}catch(Exception ex){Output.Text="Export failed: "+ex.Message;}}
 private async void SearchCve(object sender,RoutedEventArgs e){CveButton.IsEnabled=false;currentAdvisory=null;try{Output.Text="Querying public advisory catalogs...";var keyword=CveKeyword.Text.Trim();var items=await VulnerabilityCatalog.SearchAsync(keyword);var snapshot=new AdvisorySnapshot(keyword,DateTimeOffset.UtcNow,items);ShowAdvisory(snapshot,false);try{await advisoryCache.SaveAsync(snapshot);}catch(Exception ex){Output.Text+="\nCache write failed: "+ex.Message;}}catch(Exception ex){Output.Text="Advisory search failed: "+ex.Message;}finally{CveButton.IsEnabled=true;}}
}